import{_ as t,o,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"我的钱包 - 优惠券","description":"","frontmatter":{"title":"我的钱包 - 优惠券"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/wallet-coupons.md","filePath":"ops-knowledge-base/presales-support/wallet-coupons.md","lastUpdated":1788259091000}'),l={name:"ops-knowledge-base/presales-support/wallet-coupons.md"};function s(n,a,i,p,d,h){return o(),e("div",null,[...a[0]||(a[0]=[r('<h2 id="一、功能概述" tabindex="-1">一、功能概述 <a class="header-anchor" href="#一、功能概述" aria-label="Permalink to &quot;一、功能概述&quot;">​</a></h2><p>优惠券是平台提供的消费减免工具，支持按规则抵扣产品订单金额，帮助用户享受购买优惠。财务管理模块的 “优惠券” 页面支持优惠券的状态统计、查询及使用操作。</p><h2 id="二、功能入口" tabindex="-1">二、功能入口 <a class="header-anchor" href="#二、功能入口" aria-label="Permalink to &quot;二、功能入口&quot;">​</a></h2><p>通过导航路径 <strong>客户中心 / 财务管理</strong> / <strong>我的钱包</strong>进入页面后，点击顶部标签栏的 “优惠券”，即可进入优惠券管理界面。</p><h2 id="三、功能说明" tabindex="-1">三、功能说明 <a class="header-anchor" href="#三、功能说明" aria-label="Permalink to &quot;三、功能说明&quot;">​</a></h2><h3 id="一-状态统计" tabindex="-1">（一）状态统计 <a class="header-anchor" href="#一-状态统计" aria-label="Permalink to &quot;（一）状态统计&quot;">​</a></h3><p>界面顶部展示优惠券的分类统计：</p><ul><li><strong>即将到期</strong>：临近有效期的优惠券数量</li><li><strong>未使用</strong>：当前可使用的优惠券数量</li><li><strong>已使用</strong>：已完成抵扣的优惠券数量</li><li><strong>已过期</strong>：超出有效期的优惠券数量</li></ul><h3 id="二-筛选与列表信息" tabindex="-1">（二）筛选与列表信息 <a class="header-anchor" href="#二-筛选与列表信息" aria-label="Permalink to &quot;（二）筛选与列表信息&quot;">​</a></h3><ol><li><p><strong>状态筛选</strong>：通过 “状态” 下拉框选择 “全部状态”“未使用”“已使用” 等，快速筛选对应状态的优惠券。</p></li><li><p><strong>列表信息</strong>：优惠券列表展示核心内容：</p><ul><li><strong>名称 / 使用明细</strong>：优惠券的活动标识及具体使用规则（如 “12 月新用户满 100 减 25”）</li><li><strong>金额 / 折扣</strong>：优惠券的减免金额或折扣比例（如 “$25”“35%”）</li><li><strong>状态 / 续费</strong>：优惠券当前状态（如 “未使用”）及续费可用性（如 “不可用”）</li><li><strong>时间信息</strong>：包含领取日期、到期日期、使用日期（未使用则显示 “-”）</li><li><strong>操作</strong>：点击 “去使用” 可跳转至对应产品的订单页面，按规则使用该优惠券抵扣金额</li></ul></li></ol><h3 id="三-使用规则提示" tabindex="-1">（三）使用规则提示 <a class="header-anchor" href="#三-使用规则提示" aria-label="Permalink to &quot;（三）使用规则提示&quot;">​</a></h3><p>优惠券需满足对应使用条件（如 “新用户订单满 100”），且需在有效期内使用；已使用或过期的优惠券无法再次使用，可通过列表状态区分可用范围。</p>',12)])])}const u=t(l,[["render",s]]);export{c as __pageData,u as default};
